Subroutine Visitar()
  Write "abro la puerta";
  Defer
    Write "cierro la puerta";
  EndDefer
  Write "enciendo la luz";
  Defer
    Write "apago la luz";
  EndDefer
  Write "leo un rato";
EndSubroutine

Algorithm Cuarto
  Visitar();
EndAlgorithm

Function linea <- LineaStock(nombre As String, stock As Integer)
  Define linea As String;
  linea <- nombre + ";" + toText(stock);
EndFunction

Subroutine Guardar(texto As String) As Result<Integer, IoError>
  Define carpeta As DirCap <- Propagate requestDirectory(".");
  Define archivo As FileCap <- Propagate carpeta.open("stock.txt", "escritura");
  Defer
    Discard archivo.close();
  EndDefer
  Return archivo.writeText(texto);
EndSubroutine

Subroutine Cargar() As Result<String, IoError>
  Define carpeta As DirCap <- Propagate requestDirectory(".");
  Define archivo As FileCap <- Propagate carpeta.open("stock.txt", "lectura");
  Defer
    Discard archivo.close();
  EndDefer
  Return archivo.readText();
EndSubroutine

Algorithm Inventario
  Define texto As String <- LineaStock("jugo", 10) + "\n" + LineaStock("sandwich", 5) + "\n" + LineaStock("alfajor", 8) + "\n" + LineaStock("agua", 12) + "\n" + LineaStock("fruta", 6);
  Switch Guardar(texto) Do
    Success(bytes): Write "Guardado: ", bytes, " bytes";
    Failure(problema): Write "No se pudo guardar: ", problema.code;
  EndSwitch
  Switch Cargar() Do
    Success(leido): Write leido;
    Failure(problema): Write "No hay inventario guardado (", problema.code, ")";
  EndSwitch
EndAlgorithm

Subroutine Cargar() As Result<String, IoError>
  Define carpeta As DirCap <- Propagate requestDirectory(".");
  Define archivo As FileCap <- Propagate carpeta.open("stock.txt", "lectura");
  Defer
    Discard archivo.close();
  EndDefer
  Return archivo.readText();
EndSubroutine

Algorithm PrimerDia
  Switch Cargar() Do
    Success(leido): Write leido;
    Failure(problema): Write "No hay inventario guardado (", problema.code, ")";
  EndSwitch
EndAlgorithm
